% This function finds the jacobian of the transformation by computing exact
% partials.
%
% Alec Lewandowski
% 10/6/25

function [J] = partialJ(oeVec, tpe, mu)

a = oeVec(1);
e = oeVec(2);
i = oeVec(3);
aop = oeVec(4);
LAN = oeVec(5);
M0 = oeVec(6);

% Calculating mean motion first
n = sqrt(mu/a^3);

% Calculating the mean anomaly
M = M0 + n*tpe;

% Solving kepler's equation for eccentric anomaly (newton-raphson)
E = M;
tol = 1e-12;
for k = 1:50
    f = E - e*sin(E) - M;
    fp = 1 - e*cos(E);
    dE = -f/fp;
    E = E + dE;
    if abs(dE) < tol
        break;
    end
end

cg = a;
cg3 = e;

